(()=>{const add=(key,name,equipment,sets,steps,base,muscle)=>{EXERCISES[key]={name,equipment,sets,steps,tip:'Keep the movement controlled and use a comfortable range. Stop if you feel sharp pain.'};MUSCLES[muscle].parts.forEach(p=>{if(p.moves.includes(base))p.moves.push(key);});};
add('standingCurl','Standing dumbbell curl','Dumbbells','2–3 sets · 8–15 reps',['Stand tall with palms forward and elbows close to your sides.','Curl without swinging your shoulders or leaning back.','Lower slowly through a comfortable elbow range.'],'cableCurl','biceps');
add('floorPress','Dumbbell floor press','Dumbbells · floor','2–3 sets · 8–12 reps',['Lie on the floor with knees bent and dumbbells over your chest.','Lower until your upper arms gently touch the floor.','Pause, then press up with wrists stacked over elbows.'],'flatPress','chest');
add('bandRow','Seated resistance-band row','Resistance band · secure foot anchor','2–3 sets · 10–15 reps',['Sit tall with a band secured around both feet. Inspect it for damage before use.','Pull elbows toward your hips while keeping your torso steady.','Return slowly without rounding your back.'],'row','back');
add('gobletSquat','Goblet squat','Dumbbell','2–3 sets · 8–12 reps',['Hold a dumbbell securely at chest height.','Sit down between your hips with feet planted and knees tracking with your toes.','Stand smoothly and keep the load close to your body.'],'squat','quads');
add('singleLegBridge','Single-leg glute bridge','Bodyweight · floor','2–3 sets · 8–12 per side',['Lie on your back with one foot planted and the other leg lifted.','Raise the hips while keeping your pelvis level.','Lower slowly; use both feet if control is difficult.'],'hipThrust','glutes');
add('standingPress','Standing dumbbell overhead press','Dumbbells','2–3 sets · 6–10 reps',['Stand with dumbbells at shoulder height and brace your trunk.','Press overhead without leaning backward.','Lower smoothly; choose a range your shoulders tolerate.'],'shoulderPress','shoulders');
})();
